import { buildVaultTuple } from "./e4.js";

function sliderVector(ctx) {
  const values = ctx.packet.journal.values;
  const seed = `${values.resource}|${values.environment}|${values.grant}|${values.replayGuard}|${values.slider}|${ctx.packet.gesture.sequence.join('.')}`;
  return Array.from(seed).slice(0, 12).map((ch, index) => (ch.charCodeAt(0) + ctx.row.weight + index * 3) % 53);
}

function authorizeSliderChallenge(ctx) {
  const values = ctx.packet.journal.values;
  const complete = Boolean(values.resource && values.environment && values.grant && values.replayGuard === '1');
  const gesture = ctx.packet.gesture;
  const distance = Number(values.slider || gesture.distance || 0);
  const gate = complete && ctx.capability === 'vault:challenge:slider' && gesture.band === 'sweep' && gesture.sequence.join(':') === 'focus:slide:commit' && distance >= 80 && ctx.row.policy === 'seal';
  return { ...ctx, gate, gestureVector: sliderVector(ctx), journalTicket: (ctx.packet.journal.revision * 101 + ctx.row.weight * 17 + distance) >>> 0 };
}

export function validateSliderChallenge(ctx) {
  const next = authorizeSliderChallenge(ctx);
  return next.gate ? buildVaultTuple(next) : null;
}
